package net.civeira.phylax.feature.observe.observeddashboard.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observeddashboard.domain.ObservedDashboard;
import net.civeira.phylax.feature.observe.observeddashboard.domain.valueobject.SourceVariableVO;

@RequiredArgsConstructor
public class SourceVariableValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<SourceVariableVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<Boolean> getSourceVariable() {
    return value.map(SourceVariableVO::isSourceVariable);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<SourceVariableVO> getSourceVariableValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public SourceVariableVO readSourceVariable(final Optional<ObservedDashboard> original,
      final ConstraintFailList fails) {
    SourceVariableVO result =
        value.orElse(original.map(ObservedDashboard::getSourceVariableValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "sourceVariable", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param sourceVariable
   * @return
   */
  public T sourceVariable(SourceVariableVO sourceVariable) {
    this.value = Optional.of(sourceVariable);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param sourceVariable
   * @return
   */
  public T sourceVariable(Optional<SourceVariableVO> sourceVariable) {
    this.value = sourceVariable;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param sourceVariable
   * @return
   */
  public T sourceVariable(Boolean sourceVariable) {
    this.value = Optional.of(SourceVariableVO.from(sourceVariable));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetSourceVariable() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetSourceVariableIfMatches(final String field) {
    if ("sourceVariable".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
